const {Buffer} = require("buffer/");


const LGT_KEY_SEP = "<--LEGITDOC_KEY-->";

const findReverse = function (
    reversedStr,
    arr,
    startFrom
) {
    let foundLength = 0;
    let i = startFrom ? startFrom : arr.byteLength - 1;
    for (; i >= 0; i--) {
        const c = String.fromCharCode(arr[i]);
        if (c === reversedStr[foundLength]) {
            foundLength++;
            if (foundLength === reversedStr.length) {
                //Position of 's' in 'startxref' in the pdfBytes array.
                return i;
            }
        } else {
            foundLength = 0;
        }
    }
    return i;
};

const getBetween = function (str, firstStr, lastStr) {
    const matches = str.match(firstStr + "(.*)" + lastStr);
    if (!matches || matches.length < 2) {
        return false;
    }
    return matches[1].trim();
};

const STARTXREF_REVERSE = [..."startxref"].reverse().join("");
const getStartXRefPosition = function (pdfBytes) {
    return findReverse(STARTXREF_REVERSE, pdfBytes);
};

const LEGITDOC_KEY_REVERSE = [..."%<--LEGITDOC_KEY-->"].reverse().join("");
const getLegitDocKeyPos = function (pdfBytes, startFrom) {
    return findReverse(LEGITDOC_KEY_REVERSE, pdfBytes, startFrom);
};

const parseLegitDocPDF = (pdfData) => {
    let lgtKeyDataJSON, originalPDFData;
    try {
        const startXRefPos1 = getStartXRefPosition(pdfData); //find 'startxref' start position in modified data.
        const lgtKeyPos = getLegitDocKeyPos(pdfData, startXRefPos1); //find 'lgt_ket start position in modified data.
        //construct reverted data by removing the lgt_key\n before startxref
        originalPDFData = Buffer.concat([pdfData.slice(0, lgtKeyPos), pdfData.slice(startXRefPos1, pdfData.byteLength)]);
        const LGT_USER_KEY = pdfData.slice(lgtKeyPos, startXRefPos1).toString("utf-8");

        lgtKeyDataJSON = getBetween(LGT_USER_KEY, LGT_KEY_SEP, LGT_KEY_SEP);
    } catch (_e) {
        console.log(_e);
    }
    return {
        lgtKeyDataJSON,
        originalPDFData
    }
}

module.exports = parseLegitDocPDF;
