import JSZip from 'jszip';
const EC = require('elliptic').ec;
import { keccak_256 } from 'js-sha3';
// import pdfjsLib from 'pdfjs-dist/webpack';
import { expose } from 'threads/worker';
import { Subject } from 'threads/observable';
import Observable from 'zen-observable';
const MerkleTools = require('merkle-tools');
// const uuidv4 = require('uuid/v4');
import VerificationStatus from './FileVerificationStatus';
import { progressSubject, merkleTrack, blkTrack, totalTrack } from "./hashProgressVars";
import {LegitDocPDFReader} from "@/store/support/verifier/LegitDocPDFReader";
const pdfjsLib = require('pdfjs-dist/webpack');
const treeOptions = {
  hashType: 'SHA256' // optional, defaults to 'sha256'
};

const merkleTools = new MerkleTools(treeOptions);
const ec = new EC('ed25519');
const web3 = polygonWeb3;
const poi = polygonPOI;

const LGT_META = "LGT_META";

import { ISSUER_NAME, generateInvalidDocumentErrorString, ERROR_CODES} from "@/store/support/verifier/VerificationVariables";
import {polygonPOI, polygonWeb3} from "@/store/support/verifier/blockchainVars";


const UNSURE_ERROR_TEXT = 'An unknown error occurred';
const INVALID_FILE_TEXT = 'Not a valid LegitDoc pdf file';
class FileVerifier {
  constructor(file) {
    this._file = file;
    this._status = VerificationStatus.QUEUED;
    // this.uuid = uuidv4();
  }

  setStatus(status, reason) {
    this._status = status;
    // Capture the reason when the status are the following.
    switch (this._status) {
      case VerificationStatus.ERROR:
      case VerificationStatus.VALID:
      case VerificationStatus.INVALID:
      case VerificationStatus.INVALIDATED: this._message = reason;
    }
  }

  async verifyFile() {
    if (this.status !== VerificationStatus.QUEUED) {
      new Error('Invalid state. Looks like the attempt was already made to read the file.');
    }
    const lgtFileReader = new LegitDocPDFReader(this);
    try {
      const invalidReason = await lgtFileReader.read();
      if (invalidReason) {
        this.setStatus(VerificationStatus.INVALID, invalidReason);
      }
    } catch (e) {
      console.log(e);
      this.setStatus(VerificationStatus.ERROR, UNSURE_ERROR_TEXT);
    }
    totalTrack.count++;
    progressSubject.next(totalTrack);
  }
  setValidDocument(message, issueAuthority, issueTime) {
    this.setStatus(VerificationStatus.VALID, message);
    this.issueAuthority = issueAuthority;
    this.issueTime = issueTime;
  }

  setQRCode(qrCode) {
    this.qrCode = qrCode;
  }

  setDocHash(hash) {
    this.docHash = hash;
  }

  setDocName(docName) {
    this.docName = docName;
  }

  setDocMetadata(metadata) {
    this.metadata = metadata;
  }

  getDocHash() {
    return this.docHash;
  }

  getQRCode() {
    return this.qrCode;
  }

  getDocName() {
    return this.docName;
  }

  get file() {
    return this._file;
  }

  get status() {
    return this._status;
  }
}

class LegitDocZipReader {
  constructor(fileVerifier) {
    this.fileVerifier = fileVerifier;
  }
  async read() {
    this.fileVerifier.setStatus(VerificationStatus.READING);
    try {
      const loadError = await this.loadZip(this.fileVerifier.file);
      merkleTrack.count++;
      progressSubject.next(merkleTrack);
      if (loadError) return loadError;
      const verifyError = await this.checkOnBlockchain();
      blkTrack.count++;
      progressSubject.next(blkTrack);
      if (verifyError) return verifyError;
    } catch (e) {
      console.log(e);
      return UNSURE_ERROR_TEXT;
    }
  }

  async loadZip(zipFile) {
    let zip;
    try {
      const reader = new FileReaderSync();
      const zipContent = reader.readAsArrayBuffer(zipFile);
      zip = await JSZip.loadAsync(zipContent);
    } catch (e) {
      console.log(e);
      return ((e.toString().indexOf('is this a zip file ?') >= 0)
        ? INVALID_FILE_TEXT
        : "An error occurred while reading the submitted file [Code: E1001]");
    }

    if (Object.keys(zip.files).length !== 2) {
      return (INVALID_FILE_TEXT);
    }

    const zipFilePromises = [];
    zip.forEach((relativePath, zipEntry) => {
      if (zipEntry.name.endsWith('.key.pdf')) {
        zipFilePromises.push(this.readKeyFile(zip, relativePath));
      } else if (zipEntry.name.endsWith('.pdf')) {
        zipFilePromises.push(this.readOriginalFile(zip, relativePath));
      } else {
        return (INVALID_FILE_TEXT);
      }
    });

    try {
      const resolvedPromises = await Promise.all(zipFilePromises);
      // If there was any error string returned from resolved functions, return it.
      for (let i = 0; i < resolvedPromises.length; i++) {
        if (resolvedPromises[i]) {
          return (resolvedPromises[i]);
        }
      }
      // If necessary things weren't extracted from zip file, it's an invalid file.
      if (!(this.fileVerifier.getDocHash() && this.fileVerifier.getQRCode() && this.fileVerifier.getDocName())) {
        return (INVALID_FILE_TEXT);
      }
      if (this.fileVerifier.getDocHash() !== this.base64toHEX(this.fileVerifier.getQRCode().h).toLowerCase()) {
        console.log(ERROR_CODES.E1002);
        return generateInvalidDocumentErrorString("E1002");
      }
      if (!merkleTools.validateProof(this.fileVerifier.getQRCode().p, this.fileVerifier.getDocHash(), this.base64toHEX(this.fileVerifier.getQRCode().r), true)) {
        console.log(ERROR_CODES.E1003);
        return generateInvalidDocumentErrorString("E1003");
      }
    } catch (e) {
      console.log(e);
      return (UNSURE_ERROR_TEXT);
    }
  }

  async readKeyFile(zip, relativePath) {
    // Reject if key file is already read, and qrcode is set.
    if (this.fileVerifier.getQRCode()) {
      return (INVALID_FILE_TEXT);
    }
    let content, pdf, textPage;
    try {
      content = await zip.file(relativePath).async('uint8array');
    } catch (e) {
      return (`Error reading the contents of the zip file [Code E1004]. Please reload and retry. If the error persists, document might be invalid`);
    }

    try {
      pdf = await pdfjsLib.getDocument(content).promise;
    } catch (e) {
      console.log(e);
      return (`Error reading the contents of the zip file [Code E1005]. Please reload and retry. If the error persists, document might be invalid`);
    }

    let res;
    try {
      textPage = await this.getPageText(1, pdf);
      const delimiter = '<--LEGITDOC_KEY-->';
      textPage = textPage.replace(/ /g, ''); // Sometimes verification might break due to spaces in delimiter <--LEGITDOC_KEY-->
      // console.log(textPage);
      // Show the text of the page in the console
      res = JSON.parse(textPage.substring(textPage.indexOf(delimiter) + delimiter.length, textPage.lastIndexOf(delimiter)));
    } catch (e) {
      console.log(`Couldn't read key data from file: ${relativePath}`);
      return generateInvalidDocumentErrorString("E1006");
    }
    try {
      res.p = this.getHexFields(res.p);
    } catch (e) {
      return generateInvalidDocumentErrorString("E1007");
    }
    if (!this.isValidQRCode(res)) {
      return generateInvalidDocumentErrorString("E1008");
    }
    this.fileVerifier.setQRCode(res);
    pdf.destroy();
  }

  readOriginalFile(zip, relativePath) {
    return new Promise(async(resolve, reject) => {
      // Reject if original file is already read, and doc hash is set.
      if (this.fileVerifier.getDocHash()) {
        reject(INVALID_FILE_TEXT);
        return;
      }
      let content;
      try {
        content = await zip.file(relativePath).async('uint8array');
      } catch (e) {
        reject(INVALID_FILE_TEXT);
        return;
      }

      //Try reading pdf metadata. If errored, take no action.
      try {
        const pdf = await pdfjsLib.getDocument(content).promise;
        const metadata = await pdf.getMetadata();
        this.fileVerifier.setDocMetadata(metadata.info.Custom && metadata.info.Custom[LGT_META]);
        pdf.destroy();
      } catch (e) {
        console.log(e);
      }

      this.fileVerifier.setDocHash(keccak_256(content).toString('hex').toLowerCase());
      this.fileVerifier.setDocName(`${this.fileVerifier.file.name} (${relativePath})`);
      resolve();
    });
  }

  async checkOnBlockchain() {
    try {
      const root = '0x' + this.base64toHEX(this.fileVerifier.getQRCode().r).toLowerCase();
      const results = await Promise.all([poi.methods.getRootPubKey(root).call(),
        poi.methods.getAuthority(root).call(),
        poi.methods.getTime(root).call(),
        poi.methods.getInvalidated('0x' + keccak_256(root.replace('0x', '') + this.fileVerifier.getDocHash()).toString('hex')).call()
      ]);
      const rootPubKey = results[0];
      const authority = web3.utils.toUtf8(results[1]);
      const time = results[2];
      const invalidated = results[3];
      if (rootPubKey && rootPubKey.length > 0) {
        try {
          const keyPair = ec.keyFromPublic(this.base64toHEX(rootPubKey), 'hex');
          if (!keyPair.verify('0x' + this.fileVerifier.getDocHash(), this.base64toHEX(this.fileVerifier.getQRCode().s))) {
            return generateInvalidDocumentErrorString("E1009");
          }
        } catch (err) {
          return generateInvalidDocumentErrorString("E1010");
        }
      } else {
        return generateInvalidDocumentErrorString("E1011");
      }
      if (!authority || authority.length === 0) {
        return generateInvalidDocumentErrorString("E1012");
      }
      if (!time || time === '0') {
        return generateInvalidDocumentErrorString("E1013");
      }
      //ignore other issuers and compare with issuer only.
      if(authority !== ISSUER_NAME) {
        return generateInvalidDocumentErrorString("E1014");
      }
      /*const ONE_YEAR = 365 * 24 * 60 * 60 * 1000;
      if (Date.now() - time * 1000 > ONE_YEAR) {
        return `This document has expired the one year limit. It was issued by ${authority} on ${new Date(time * 1000)}`;
      }*/
      if (!invalidated || invalidated === '0') {
        this.fileVerifier.setValidDocument(`This certificate was issued by ${authority} on ${new Date(time * 1000)}`, authority, time);
      } else {
        this.fileVerifier.setStatus(VerificationStatus.INVALIDATED, `This certificate is no longer valid. This was invalidated by ${authority} on ${new Date(invalidated * 1000)}`);
      }
    } catch (e) {
      this.fileVerifier.setStatus(VerificationStatus.ERROR, 'Network error while verifying on Blockchain');
    }
  }

  async getPageText(pageNum, PDFDocumentInstance) {
    // Return a Promise that is solved once the text of the page is retrieven
    return new Promise(async(resolve, reject) => {
      let pdfPage, textContent;
      try {
        pdfPage = await PDFDocumentInstance.getPage(pageNum);
      } catch (e) {
        reject(e);
        return;
      }

      try {
        textContent = await pdfPage.getTextContent();
      } catch (e) {
        reject(e);
        return;
      }

      const textItems = textContent.items;
      let finalString = '';

      // Concatenate the string of the item to the final string
      for (let i = 0; i < textItems.length; i++) {
        const item = textItems[i];

        finalString += item.str + ' ';
      }
      // Solve promise with the text retrieved from the page
      resolve(finalString);
    });
  }

  getHexFields(array) {
    const hexArray = [];
    for (let i = 0; i < array.length; i++) {
      const hexobj = {};
      for (const k in array[i]) {
        if (array[i].hasOwnProperty(k)) {
          hexobj[k === 'r' ? 'right' : 'left'] = Buffer.from(array[i][k], 'base64').toString('hex');
        }
      }
      hexArray.push(hexobj);
    }
    return hexArray;
  }

  isValidQRCode(obj) {
    return !!(obj.h && obj.r && obj.s && obj.p && obj.i);
  }

  base64toHEX(base64) {
    const raw = atob(base64);
    let HEX = '';
    for (let i = 0; i < raw.length; i++) {
      const _hex = raw.charCodeAt(i).toString(16);
      HEX += (_hex.length === 2 ? _hex : '0' + _hex);
    }
    return HEX.toUpperCase();
  }
}

