const fileHasher = {
  async hashFiles(files) {
    merkleTrack.count = 0; // Reset the track counters
    blkTrack.count = 0;
    const fvs = [];
    const verificationTasks = [];
    for (let i = 0; i < files.length; i++) {
      const fileVerifier = new FileVerifier(files[i]);
      verificationTasks.push(fileVerifier.verifyFile());
      fvs.push(fileVerifier);
    }
    try {
      await Promise.all(verificationTasks);
    } catch (e) { console.log(e); } // Shouldn't throw. If someone edits the code, let this capture errors.
    progressSubject.complete();
    return fvs;
  },
  progressObservable() {
    return Observable.from(progressSubject);
  }
};
expose(fileHasher);
